/* ============================================================================
 * Plexpoint Explorer V171 — FAST ROW CLIPPING BELOW FIXED CHROME
 *
 * Keep FileBrowser's native #main scroller and the light glass chrome. Rows
 * fully behind the chrome are hidden, while only the one crossing its lower
 * edge receives a small clip. This avoids repainting the entire listing on
 * every scroll frame.
 * ========================================================================== */
(() => {
  "use strict";

  const STYLE_ID = "plexpoint-v171-list-chrome-clip-style";
  const GUARD_STYLE_ID = "plexpoint-v173-list-chrome-guard-style";
  const TRACK_ATTRIBUTE = "data-plexpoint-v171-track";
  const PENDING_CLASS = "plexpoint-v171-rows-pending";

  let scrollHost = null;
  let trackedListing = null;
  let trackedItems = [];
  let chromeBottom = 0;
  let structureFrame = 0;
  let dynamicSheet = null;
  let nextTrackId = 0;
  let structureObserver = null;
  let geometryObserver = null;
  let geometryTargets = [];

  function ensureGuardStyles() {
    if (document.getElementById(GUARD_STYLE_ID)) return;

    const style = document.createElement("style");
    style.id = GUARD_STYLE_ID;
    style.textContent = `
      @media (min-width: 769px) {
        html.${PENDING_CLASS}
          body.plexpoint-explorer-layout
          .listing-view-root > .listing-items .listing-item,
        html.${PENDING_CLASS}
          body.plexpoint-explorer-layout
          .listing-view-root > .listing-items h2 {
          visibility: hidden !important;
          pointer-events: none !important;
        }
      }
    `;
    document.head.appendChild(style);
  }

  function beginStructureChange() {
    if (
      window.innerWidth > 768 &&
      String(location.pathname || "").startsWith("/files/")
    ) {
      document.documentElement.classList.add(PENDING_CLASS);
    }
    scheduleStructure();
  }

  function ensureStyles() {
    if (document.getElementById(STYLE_ID)) return;

    const style = document.createElement("style");
    style.id = STYLE_ID;
    style.textContent = "";
    document.head.appendChild(style);
    dynamicSheet = style.sheet;
  }

  function getDynamicSheet() {
    ensureStyles();
    if (dynamicSheet) return dynamicSheet;
    dynamicSheet = document.getElementById(STYLE_ID)?.sheet || null;
    return dynamicSheet;
  }

  function visibleBottom(element) {
    if (!(element instanceof HTMLElement)) return 0;
    const computed = getComputedStyle(element);
    if (
      computed.display === "none" ||
      computed.visibility === "hidden" ||
      Number(computed.opacity) === 0
    ) {
      return 0;
    }

    const rect = element.getBoundingClientRect();
    if (rect.width <= 0 || rect.height <= 0 || rect.bottom <= 0) return 0;
    return rect.bottom;
  }

  function clearItem(item) {
    const element = item?.element;
    if (!(element instanceof HTMLElement)) return;
    item.rule?.style && (item.rule.style.cssText = "");
    if (item.trackValue) element.removeAttribute(TRACK_ATTRIBUTE);
    item.state = "clear";
    item.clip = "";
  }

  function setItemState(item, state, clip = "") {
    const ruleStyle = item.rule?.style;
    if (!ruleStyle) return;

    if (state === "hidden") {
      if (item.state !== state) {
        ruleStyle.cssText = "";
        ruleStyle.setProperty("visibility", "hidden", "important");
        ruleStyle.setProperty("pointer-events", "none", "important");
      }
    } else if (state === "partial") {
      if (item.state !== state) {
        ruleStyle.cssText = "";
      }
      if (item.clip !== clip) {
        ruleStyle.setProperty(
          "clip-path",
          `inset(${clip} 0 0 0)`,
          "important"
        );
      }
    } else if (item.state !== "clear") {
      ruleStyle.cssText = "";
    }

    item.state = state;
    item.clip = clip;
  }

  function paintRows() {
    if (
      !(scrollHost instanceof HTMLElement) ||
      !scrollHost.isConnected ||
      !(trackedListing instanceof HTMLElement) ||
      !trackedListing.isConnected
    ) {
      scheduleStructure();
      return;
    }

    const scrollTop = scrollHost.scrollTop;
    for (const item of trackedItems) {
      if (!item.element.isConnected) continue;

      const top = item.anchorTop - scrollTop;
      const bottom = top + item.height;
      if (bottom <= chromeBottom + .5) {
        setItemState(item, "hidden");
      } else if (top < chromeBottom) {
        const clip = `${Math.ceil(chromeBottom - top)}px`;
        setItemState(item, "partial", clip);
      } else {
        setItemState(item, "clear");
      }
    }
  }

  function rowStructureNode(node) {
    if (!(node instanceof Element)) return false;
    return (
      node.matches(".listing-item, .listing-view-root, .listing-items, h2") ||
      Boolean(node.querySelector(".listing-item, .listing-view-root, .listing-items, h2"))
    );
  }

  function rowStructureChanged(records) {
    for (const record of records) {
      if (
        record.type === "attributes" &&
        record.target instanceof Element &&
        (record.target.closest(".listing-item") || record.target.matches("#main, .listing-view-root, .listing-items"))
      ) {
        return true;
      }
      for (const node of record.addedNodes) {
        if (rowStructureNode(node)) return true;
      }
      for (const node of record.removedNodes) {
        if (rowStructureNode(node)) return true;
      }
    }
    return false;
  }

  function observeScrollHost() {
    structureObserver?.disconnect();
    structureObserver = null;
    if (!(scrollHost instanceof HTMLElement)) return;

    structureObserver = new MutationObserver((records) => {
      if (!rowStructureChanged(records)) return;
      /* MutationObserver runs before paint, so new rows never get one visible
         frame behind the fixed address/toolbar/shelf chrome. */
      scheduleStructure();
    });
    structureObserver.observe(scrollHost, {
      childList: true,
      subtree: true,
      attributes: true,
      attributeFilter: ["id", "href", "data-name", "aria-label", "style", "class"],
    });
  }

  function bindScrollHost(nextHost) {
    if (scrollHost === nextHost) return;
    scrollHost?.removeEventListener("scroll", paintRows);
    scrollHost = nextHost instanceof HTMLElement ? nextHost : null;
    scrollHost?.addEventListener("scroll", paintRows, { passive: true });
    observeScrollHost();
  }

  function observeGeometry() {
    if (typeof ResizeObserver !== "function") return;
    const targets = [scrollHost, document.querySelector("header.flexbar"),
      document.getElementById("shelf"), trackedListing?.parentElement,
      trackedListing, trackedItems[0]?.element].filter(element => element instanceof HTMLElement);
    if (targets.length === geometryTargets.length && targets.every((element, index) => element === geometryTargets[index])) return;
    geometryObserver ||= new ResizeObserver(scheduleStructure);
    geometryObserver.disconnect();
    geometryTargets = targets;
    for (const element of targets) geometryObserver.observe(element);
  }

  function refreshStructure() {
    structureFrame = 0;
    ensureStyles();
    ensureGuardStyles();

    for (const item of trackedItems) clearItem(item);
    trackedItems = [];
    trackedListing = null;

    const sheet = getDynamicSheet();
    if (sheet) {
      while (sheet.cssRules.length) sheet.deleteRule(0);
    }

    const nextHost = document.getElementById("main");
    bindScrollHost(nextHost);

    if (
      !(scrollHost instanceof HTMLElement) ||
      window.innerWidth <= 768 ||
      !document.body?.classList.contains("plexpoint-explorer-layout")
    ) {
      observeGeometry();
      document.documentElement.classList.remove(PENDING_CLASS);
      return;
    }

    chromeBottom = Math.ceil(Math.max(
      visibleBottom(document.querySelector("header.flexbar")),
      visibleBottom(document.getElementById("shelf"))
    ));

    const scrollTop = scrollHost.scrollTop;
    trackedListing = document.querySelector(
      ".listing-view-root > .listing-items"
    );
    const elements = document.querySelectorAll(
      ".listing-view-root > .listing-items .listing-item, " +
      ".listing-view-root > .listing-items h2"
    );

    trackedItems = Array.from(elements, (element) => {
      const rect = element.getBoundingClientRect();
      let selector = "";
      let trackValue = "";

      if (element.id) {
        selector = `#${CSS.escape(element.id)}`;
      } else {
        trackValue = String(nextTrackId++);
        element.setAttribute(TRACK_ATTRIBUTE, trackValue);
        selector = `[${TRACK_ATTRIBUTE}="${trackValue}"]`;
      }

      let rule = null;
      if (sheet) {
        const index = sheet.cssRules.length;
        sheet.insertRule(
          `body.plexpoint-explorer-layout ${selector} {}`,
          index
        );
        rule = sheet.cssRules[index] || null;
      }

      return {
        element,
        trackValue,
        rule,
        anchorTop: rect.top + scrollTop,
        height: rect.height,
        state: "clear",
        clip: "",
      };
    }).filter((item) => item.height > 0);

    observeGeometry();
    paintRows();
    document.documentElement.classList.remove(PENDING_CLASS);
  }

  function scheduleStructure() {
    if (structureFrame) return;
    structureFrame = requestAnimationFrame(refreshStructure);
  }

  function checkStructure() {
    const currentHost = document.getElementById("main");
    const currentListing = document.querySelector(
      ".listing-view-root > .listing-items"
    );
    if (currentHost !== scrollHost || currentListing !== trackedListing) {
      beginStructureChange();
    }
  }

  function installHistoryGuard() {
    if (history.__plexpointV171RouteGuard) return;

    for (const methodName of ["pushState", "replaceState"]) {
      const original = history[methodName];
      history[methodName] = function plexpointV171HistoryGuard(...args) {
        let changesFilesRoute = false;
        try {
          const next = new URL(args[2] ?? location.href, location.href);
          changesFilesRoute =
            next.origin === location.origin &&
            next.pathname.startsWith("/files/") &&
            `${next.pathname}${next.search}${next.hash}` !==
              `${location.pathname}${location.search}${location.hash}`;
        } catch (_error) {}
        if (changesFilesRoute) beginStructureChange();
        const result = original.apply(this, args);
        if (changesFilesRoute) scheduleStructure();
        return result;
      };
    }

    try {
      Object.defineProperty(history, "__plexpointV171RouteGuard", {
        value: true,
        configurable: true,
      });
    } catch (_error) {
      history.__plexpointV171RouteGuard = true;
    }
  }

  function start() {
    ensureStyles();
    ensureGuardStyles();
    installHistoryGuard();
    refreshStructure();

    window.addEventListener("resize", scheduleStructure, { passive: true });
    window.addEventListener("popstate", beginStructureChange, { passive: true });
    window.addEventListener("hashchange", beginStructureChange, { passive: true });
    window.addEventListener("load", scheduleStructure, { once: true });

    /* Vue route changes can replace the listing without a popstate event. A
       sparse identity check catches that without observing every DOM change. */
    document.addEventListener("click", () => {
      queueMicrotask(checkStructure);
    }, { capture: true, passive: true });
    window.setInterval(checkStructure, 750);
  }

  ensureGuardStyles();
  if (String(location.pathname || "").startsWith("/files/")) {
    document.documentElement.classList.add(PENDING_CLASS);
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", start, { once: true });
  } else {
    start();
  }
})();

