    // FileBrowser can leave its selection/add header behind when a native Home
    // row is right-clicked. It is not part of the compact Home-folder menu.
    for (const button of Array.from(menu.querySelectorAll("button:not(.action)"))) {
      const icon = button.querySelector("i")?.textContent?.trim().toLowerCase() || "";
      const text = button.textContent?.replace(button.querySelector("i")?.textContent || "", "").trim() || "";
      if (!text && ["add", "add_circle", "add_circle_outline"].includes(icon)) button.remove();
    }
    menu.querySelectorAll(".selected-count-header, .selected-count, [data-plexpoint-selection-count=\"true\"]").forEach((element) => element.remove());

    const actions = Array.from(menu.querySelectorAll("button.action"));

    // The menu now opens only after the previous prompt is fully gone and the
    // synthetic folder object is already selected, so there is no stale drive
    // action list to repair. Reveal and compact this one menu immediately.
