    menu.style.visibility = "";
    state.homeContextRetrying = false;
    state.homeContextRetryCount = 0;
    document.body.classList.remove("plexpoint-home-context-pending");

    const parent = actions[0]?.parentElement || menu;
    const wanted = new Set(["share", "download", "access rules", "info", "properties"]);
    for (const action of actions) {
      const label = contextActionLabel(action);
      if (!wanted.has(label)) action.remove();
    }

    let compactNew = menu.querySelector('[data-plexpoint-compact-new="true"]');
    if (!(compactNew instanceof HTMLButtonElement)) {
      compactNew = createMenuAction("New", "add", () => {});
      compactNew.dataset.plexpointCompactNew = "true";
    }
    compactNew.disabled = false;
    if (!compactNew.isConnected) parent.appendChild(compactNew);

    let unpin = menu.querySelector('button[data-plexpoint-compact-unpin="true"]') ||
      actionByLabels(menu, ["unpin from home"]);
    if (!(unpin instanceof HTMLButtonElement)) {
      unpin = createMenuAction("Unpin from Home", "keep_off", () => {});
    }

