/* === Plexpoint Explorer V10: remove bottom status bar + move selection into sidebar === */
(function () {
  "use strict";

  const STYLE_ID = "plexpoint-v10-sidebar-selection-status-style";
  const STATUS_ID = "plexpoint-sidebar-selection-status";

  let refreshFrame = null;

  function injectStyle() {
    if (document.getElementById(STYLE_ID)) return;

    const style = document.createElement("style");
    style.id = STYLE_ID;

    style.textContent = `
      @media (min-width: 769px) {
        /*
         * The native FileBrowser status bar is fixed over the bottom of the
         * listing. Remove it entirely in the Explorer layout so the final
         * rows can actually reach the visible bottom of the window.
         */
        body.plexpoint-explorer-layout #status-bar {
          display: none !important;
          visibility: hidden !important;
          opacity: 0 !important;
          pointer-events: none !important;
          height: 0 !important;
          min-height: 0 !important;
          max-height: 0 !important;
          bottom: auto !important;
        }

        /*
         * The gallery/list Size slider lives inside that status bar, so this
         * also guarantees it cannot appear elsewhere through an old rule.
         */
        body.plexpoint-explorer-layout
          #status-bar .status-controls,
        body.plexpoint-explorer-layout
          #status-bar .gallery-size-control,
        body.plexpoint-explorer-layout
          #status-bar #gallery-size {
          display: none !important;
        }

        /*
         * Reserve a small bottom area in the sidebar for selection info.
         */
        body.plexpoint-explorer-layout #sidebar {
          padding-bottom: 58px !important;
        }

        body.plexpoint-explorer-layout
          #${STATUS_ID} {
          position: absolute !important;
          left: 16px !important;
          right: 14px !important;
          bottom: 14px !important;
          z-index: 5 !important;

          display: flex !important;
          align-items: center !important;
          gap: 7px !important;

          min-height: 28px !important;
          padding: 4px 6px !important;
          margin: 0 !important;

          color: var(--plexpoint-explorer-muted) !important;
          font-size: 13px !important;
          font-weight: 500 !important;
          line-height: 1.25 !important;

          background: transparent !important;
          border: 0 !important;
          box-shadow: none !important;
          pointer-events: none !important;
          user-select: none !important;
          overflow: hidden !important;
          white-space: nowrap !important;
          text-overflow: ellipsis !important;
        }

        body.plexpoint-explorer-layout
          #${STATUS_ID}[hidden] {
          display: none !important;
        }

        body.plexpoint-explorer-layout
          #${STATUS_ID} .plexpoint-sidebar-selection-dot {
          flex: 0 0 8px !important;
          width: 8px !important;
          height: 8px !important;
          border-radius: 999px !important;
          background: var(--primaryColor, #2196f3) !important;
          opacity: .9 !important;
        }

        body.plexpoint-explorer-layout
          #${STATUS_ID} .plexpoint-sidebar-selection-text {
          min-width: 0 !important;
          overflow: hidden !important;
          text-overflow: ellipsis !important;
          white-space: nowrap !important;
        }
      }
    `;

    document.head.appendChild(style);
  }

  function ensureSidebarStatus() {
    const sidebar = document.getElementById("sidebar");
    if (!(sidebar instanceof HTMLElement)) return null;

    let status = document.getElementById(STATUS_ID);

    if (!(status instanceof HTMLElement)) {
      status = document.createElement("div");
      status.id = STATUS_ID;
      status.hidden = true;
      status.setAttribute("aria-live", "polite");
      status.setAttribute("aria-atomic", "true");

      const dot = document.createElement("span");
      dot.className = "plexpoint-sidebar-selection-dot";
      dot.setAttribute("aria-hidden", "true");

      const label = document.createElement("span");
      label.className = "plexpoint-sidebar-selection-text";

      status.append(dot, label);
      sidebar.appendChild(status);
    } else if (status.parentElement !== sidebar) {
      sidebar.appendChild(status);
    }

    return status;
  }

  function getSelectedStatusText() {
    // Search shares the same sidebar footer as normal selection feedback.
    // Read the current render so counts, loading and errors stay in sync.
    if (document.body.classList.contains("plexpoint-search-results-active")) {
      return document.querySelector("#plexpoint-search-results .plexpoint-search-result-status")?.textContent?.trim() || "";
    }
    const nativeStatus = document.getElementById("status-bar");
    if (!(nativeStatus instanceof HTMLElement)) {
      return "";
    }

    const info = nativeStatus.querySelector(".status-info");
    if (!(info instanceof HTMLElement)) {
      return "";
    }

    /*
     * FileBrowser only renders .status-info .button when selectedCount > 0.
     * This lets us distinguish:
     *   "1 item selected (6.4 GB)"
     * from ordinary directory totals such as:
     *   "12 folders | 5 files (80 GB)".
     */
    const selectedCount = info.querySelector(":scope > .button");
    if (!(selectedCount instanceof HTMLElement)) {
      return "";
    }

    return String(info.textContent || "")
      .replace(/\s+/g, " ")
      .trim();
  }

  function syncSidebarStatus() {
    if (!document.body.classList.contains("plexpoint-explorer-layout")) {
      return;
    }

    const status = ensureSidebarStatus();
    if (!(status instanceof HTMLElement)) return;

    const text = getSelectedStatusText();
    const label = status.querySelector(
      ".plexpoint-sidebar-selection-text"
    );

    if (!(label instanceof HTMLElement)) return;

    if (!text) {
      if (label.textContent) label.textContent = "";
      if (!status.hidden) status.hidden = true;
      return;
    }

    if (label.textContent !== text) {
      label.textContent = text;
      status.title = text;
    }

    if (status.hidden) status.hidden = false;
  }

  function scheduleSync() {
    if (refreshFrame !== null) return;

    refreshFrame = requestAnimationFrame(() => {
      refreshFrame = null;
      syncSidebarStatus();
    });
  }

  const observer = new MutationObserver(scheduleSync);

  function start() {
    injectStyle();
    scheduleSync();

    /*
     * Selection changes are rendered by Vue inside #status-bar, and sidebar /
     * route rerenders can replace either element. Observe DOM changes and only
     * update when the final text is actually different.
     */
    observer.observe(document.documentElement, {
      childList: true,
      subtree: true,
      characterData: true,
    });

    window.addEventListener("pageshow", scheduleSync);
    window.addEventListener("popstate", scheduleSync);
    window.addEventListener("hashchange", scheduleSync);
  }

  if (document.readyState === "loading") {
    document.addEventListener(
      "DOMContentLoaded",
      start,
      { once: true }
    );
  } else {
    start();
  }
})();



