/* === Plexpoint Explorer V24: remove non-Details header gap + stray blue selection dot === */
(function () {
  "use strict";

  const STYLE_ID =
    "plexpoint-v24-non-details-gap-dot-fix-style";

  function injectStyle() {
    if (document.getElementById(STYLE_ID)) return;

    const style = document.createElement("style");
    style.id = STYLE_ID;

    style.textContent = `
      @media (min-width: 769px) {
        /*
         * =============================================================
         * NON-DETAILS VIEWS USE THE SPACE WHERE THE COLUMN HEADER WAS
         * =============================================================
         *
         * The body still carries .plexpoint-explorer-has-listing-header
         * because the native header exists in the DOM even when View !=
         * Details. An older Explorer rule therefore keeps 2.9rem of padding
         * above the listing.
         *
         * Override that only for non-Details views. #main already reserves the
         * address/toolbar area, so these views can begin almost immediately.
         */
        body.plexpoint-explorer-layout:not(.plexpoint-view-details):not(.plexpoint-home-dashboard)
          .listing-view-root {
          padding-top: .15rem !important;
        }

        /*
         * Keep every non-Details listing itself tight to the top of its root.
         * This prevents view-specific top margins/padding from recreating the
         * old category/header strip.
         */
        body.plexpoint-explorer-layout:not(.plexpoint-view-details):not(.plexpoint-home-dashboard)
          .listing-view-root > .listing-items {
          margin-top: 0 !important;
        }

        /*
         * =============================================================
         * FIX THE TINY BLUE DOT
         * =============================================================
         *
         * V17 forced .selection-rectangle to display:block permanently.
         * FileBrowser keeps that rectangle in the DOM even when it is 0x0, so
         * its blue selection styling shows as a tiny dot in the top-left.
         *
         * Hide it normally...
         */
        body.plexpoint-explorer-layout:not(.plexpoint-home-dashboard)
          .listing-view-root .selection-rectangle {
          display: none !important;
          visibility: hidden !important;
        }

        /*
         * ...and only show it when FileBrowser says rectangle selection is
         * actively happening. This preserves click-drag multi-selection.
         */
        body.plexpoint-explorer-layout:not(.plexpoint-home-dashboard)
          .listing-items.rectangle-selecting
          > .selection-rectangle {
          display: block !important;
          visibility: visible !important;
          pointer-events: none !important;
        }

        /*
         * Details keeps the existing 2.9rem spacing/header system untouched.
         */
        body.plexpoint-explorer-layout.plexpoint-view-details:not(.plexpoint-home-dashboard)
          .listing-view-root {
          /* deliberately no override */
        }
      }
    `;

    document.head.appendChild(style);
  }

  if (document.readyState === "loading") {
    document.addEventListener(
      "DOMContentLoaded",
      injectStyle,
      { once: true }
    );
  } else {
    injectStyle();
  }
})();



