/* === Plexpoint Explorer V35: SIDEBAR NAVIGATION source selector rebuilt from scratch === */
(function () {
  "use strict";

  const STYLE_ID =
    "plexpoint-v35-source-selector-style";

  const HOST_CLASS =
    "plexpoint-v35-source-selector-host";

  const BUTTON_CLASS =
    "plexpoint-v35-source-selector-button";

  const MENU_CLASS =
    "plexpoint-v35-source-selector-menu";

  const OPTION_CLASS =
    "plexpoint-v35-source-selector-option";

  let frame = null;
  let rendering = false;

  function clean(value) {
    return String(value || "")
      .replace(/\s+/g, " ")
      .trim();
  }

  function sourceKind(label) {
    const name = clean(label).toLowerCase();

    if (name === "home") {
      return "home";
    }

    if (name.includes("zima")) {
      return "system";
    }

    if (
      name.includes("usb") ||
      name.includes("sandisk") ||
      name.includes("flash")
    ) {
      return "usb";
    }

    if (
      name.includes("hdd") ||
      name.includes("hard drive") ||
      name.includes("disk")
    ) {
      return "drive";
    }

    return "folder";
  }

  function sourceRank(kind) {
    switch (kind) {
      case "home":
        return 0;
      case "system":
        return 1;
      case "drive":
        return 2;
      case "usb":
        return 3;
      case "folder":
        return 4;
      default:
        return 5;
    }
  }

  function iconForSource(label) {
    const kind = sourceKind(label);

    switch (kind) {
      case "home":
        return {
          kind,
          symbol: "home",
        };

      case "system":
        return {
          kind,
          symbol: "hard_drive",
        };

      case "drive":
        return {
          kind,
          symbol: "hard_drive",
        };

      case "usb":
        return {
          kind,
          symbol: "usb",
        };

      default:
        return {
          kind,
          symbol: "folder",
        };
    }
  }

  function vueInstanceFromElement(element) {
    if (!(element instanceof Element)) {
      return null;
    }

    if (element.__vueParentComponent) {
      return element.__vueParentComponent;
    }

    for (const key of Object.keys(element)) {
      if (
        key.startsWith("__vueParentComponent") &&
        element[key]
      ) {
        return element[key];
      }
    }

    return null;
  }

  function findLinksProxy() {
    const host = document.querySelector(
      "#sidebar .source-card-container"
    );

    if (!(host instanceof HTMLElement)) {
      return null;
    }

    let instance = vueInstanceFromElement(host);
    let depth = 0;

    while (instance && depth < 30) {
      const proxy =
        instance.proxy ||
        instance.exposed ||
        instance.ctx ||
        null;

      if (
        proxy &&
        typeof proxy.navigateToSource === "function" &&
        Array.isArray(proxy.sourceDropdownOptions)
      ) {
        return proxy;
      }

      instance = instance.parent || null;
      depth += 1;
    }

    return null;
  }

  function normalizedSourceOptions(proxy) {
    if (!proxy) {
      return [];
    }

    const raw = Array.isArray(
      proxy.sourceDropdownOptions
    )
      ? proxy.sourceDropdownOptions
      : [];

    const entries = raw
      .map((option, index) => {
        const label = clean(
          option?.label ?? option?.value
        );

        const value =
          option?.value ?? option?.label;

        if (!label || value == null) {
          return null;
        }

        const kind = sourceKind(label);

        return {
          label,
          value,
          kind,
          rank: sourceRank(kind),
          index,
        };
      })
      .filter(Boolean);

    /*
     * Required order:
     * Home -> Zima/System drive -> HDDs -> USB -> folders.
     *
     * Keep FileBrowser's original order inside each group so numbered disks
     * stay in the expected order.
     */
    entries.sort((a, b) => {
      if (a.rank !== b.rank) {
        return a.rank - b.rank;
      }

      return a.index - b.index;
    });

    return entries;
  }

  function injectStyle() {
    if (document.getElementById(STYLE_ID)) {
      return;
    }

    const style = document.createElement("style");
    style.id = STYLE_ID;

    style.textContent = `
      /*
       * =============================================================
       * HIDE FILEBROWSER'S OLD SOURCE CARD + EXPAND DROPDOWN VISUALLY
       * =============================================================
       *
       * They remain mounted so their Vue component keeps providing live
       * source data. V35 does NOT click or overlay either of them.
       */
      #sidebar
        .source-card-container.${HOST_CLASS}
        > .navigation-source-card,
      #sidebar
        .source-card-container.${HOST_CLASS}
        > .sidebar-source-switcher {
        display: none !important;
      }

      /*
       * Remove legacy source-card visual rules from the host.
       */
      #sidebar
        .source-card-container.${HOST_CLASS} {
        position: relative !important;

        width: 100% !important;
        max-width: 100% !important;

        margin: 0 0 .45em 0 !important;
        padding: 0 !important;

        overflow: visible !important;

        border: 0 !important;
        border-bottom: 0 !important;

        background: transparent !important;
        box-shadow: none !important;
      }

      /*
       * =============================================================
       * ONE REAL BUTTON
       * =============================================================
       */
      #sidebar .${BUTTON_CLASS} {
        width: 100% !important;
        min-height: 3.2em !important;

        box-sizing: border-box !important;

        margin: 0 !important;
        padding: .55em .72em !important;

        display: grid !important;
        grid-template-columns:
          1.55em minmax(0, 1fr) 1.35em !important;
        align-items: center !important;
        column-gap: .72em !important;

        color: var(--textPrimary) !important;
        background:
          color-mix(
            in srgb,
            var(--surfaceSecondary) 22%,
            transparent
          ) !important;

        border:
          1px solid
          var(--surfaceSecondary) !important;
        border-radius: .65em !important;

        box-shadow: none !important;

        font: inherit !important;
        text-align: left !important;

        cursor: pointer !important;

        transition:
          background .14s ease,
          border-color .14s ease !important;
      }

      #sidebar .${BUTTON_CLASS}:hover {
        background:
          color-mix(
            in srgb,
            var(--surfaceSecondary) 48%,
            transparent
          ) !important;
      }

      #sidebar .${BUTTON_CLASS}:focus-visible {
        outline:
          2px solid
          color-mix(
            in srgb,
            var(--primaryColor) 65%,
            transparent
          ) !important;

        outline-offset: 1px !important;
      }

      #sidebar .${BUTTON_CLASS}[aria-expanded="true"] {
        background:
          color-mix(
            in srgb,
            var(--surfaceSecondary) 45%,
            transparent
          ) !important;

        border-color:
          color-mix(
            in srgb,
            var(--textSecondary) 52%,
            var(--surfaceSecondary)
          ) !important;
      }

      #sidebar .${BUTTON_CLASS}
        .plexpoint-v35-source-icon {
        grid-column: 1 !important;

        width: 1.55em !important;
        height: 1.55em !important;

        margin: 0 !important;
        padding: 0 !important;

        display: inline-flex !important;
        align-items: center !important;
        justify-content: center !important;

        color: var(--primaryColor) !important;

        font-size: 1.35rem !important;
        line-height: 1 !important;

        pointer-events: none !important;
      }

      #sidebar .${BUTTON_CLASS}
        .plexpoint-v35-source-icon[data-kind="drive"],
      #sidebar .${BUTTON_CLASS}
        .plexpoint-v35-source-icon[data-kind="system"],
      #sidebar .${BUTTON_CLASS}
        .plexpoint-v35-source-icon[data-kind="usb"] {
        color: var(--textSecondary) !important;
      }

      #sidebar .${BUTTON_CLASS}
        .plexpoint-v35-source-label {
        grid-column: 2 !important;

        min-width: 0 !important;

        color: var(--textPrimary) !important;

        overflow: hidden !important;
        text-overflow: ellipsis !important;
        white-space: nowrap !important;

        pointer-events: none !important;
      }

      #sidebar .${BUTTON_CLASS}
        .plexpoint-v35-source-chevron {
        grid-column: 3 !important;

        justify-self: end !important;

        width: 1.35em !important;
        height: 1.35em !important;

        margin: 0 !important;
        padding: 0 !important;

        display: inline-flex !important;
        align-items: center !important;
        justify-content: center !important;

        color: var(--textSecondary) !important;

        background: transparent !important;
        border: 0 !important;
        box-shadow: none !important;

        font-size: 1.25rem !important;
        line-height: 1 !important;

        transform: rotate(0deg) !important;
        transition: transform .16s ease !important;

        pointer-events: none !important;
      }

      #sidebar .${BUTTON_CLASS}[aria-expanded="true"]
        .plexpoint-v35-source-chevron {
        transform: rotate(180deg) !important;
      }

      /*
       * =============================================================
       * CUSTOM DROPDOWN
       * =============================================================
       */
      #sidebar .${MENU_CLASS} {
        position: absolute !important;

        top: calc(100% + .38em) !important;
        left: 0 !important;
        right: 0 !important;

        z-index: 1005 !important;

        box-sizing: border-box !important;

        width: 100% !important;
        max-height: min(26rem, 58vh) !important;

        margin: 0 !important;
        padding: .36em !important;

        overflow-x: hidden !important;
        overflow-y: auto !important;

        background: var(--background) !important;

        border:
          1px solid
          var(--surfaceSecondary) !important;
        border-radius: .65em !important;

        box-shadow:
          0 .55em 1.5em
          rgba(0, 0, 0, .28) !important;

      }

      #sidebar .${OPTION_CLASS} {
        width: 100% !important;
        min-height: 2.55em !important;

        box-sizing: border-box !important;

        margin: 0 !important;
        padding: .48em .62em !important;

        display: grid !important;
        grid-template-columns:
          1.45em minmax(0, 1fr) !important;
        align-items: center !important;
        column-gap: .68em !important;

        color: var(--textPrimary) !important;
        background: transparent !important;

        border: 0 !important;
        border-radius: .45em !important;

        font: inherit !important;
        text-align: left !important;

        cursor: pointer !important;
      }

      #sidebar .${OPTION_CLASS}:hover,
      #sidebar .${OPTION_CLASS}:focus-visible {
        background:
          color-mix(
            in srgb,
            var(--surfaceSecondary) 55%,
            transparent
          ) !important;

        outline: none !important;
      }

      #sidebar .${OPTION_CLASS}[aria-current="true"] {
        background:
          color-mix(
            in srgb,
            var(--surfaceSecondary) 70%,
            transparent
          ) !important;
      }

      #sidebar .${OPTION_CLASS}
        .plexpoint-v35-option-icon {
        width: 1.45em !important;
        height: 1.45em !important;

        margin: 0 !important;
        padding: 0 !important;

        display: inline-flex !important;
        align-items: center !important;
        justify-content: center !important;

        color: var(--primaryColor) !important;

        font-size: 1.22rem !important;
        line-height: 1 !important;

        pointer-events: none !important;
      }

      #sidebar .${OPTION_CLASS}
        .plexpoint-v35-option-icon[data-kind="drive"],
      #sidebar .${OPTION_CLASS}
        .plexpoint-v35-option-icon[data-kind="system"],
      #sidebar .${OPTION_CLASS}
        .plexpoint-v35-option-icon[data-kind="usb"] {
        color: var(--textSecondary) !important;
      }

      #sidebar .${OPTION_CLASS}
        .plexpoint-v35-option-label {
        min-width: 0 !important;

        overflow: hidden !important;
        text-overflow: ellipsis !important;
        white-space: nowrap !important;

        pointer-events: none !important;
      }

      /*
       * Folder locations live at the bottom, separated from physical drives.
       */
      #sidebar .${OPTION_CLASS}.plexpoint-v35-folder-start {
        margin-top: .36em !important;
        padding-top: .72em !important;

        border-top:
          1px solid
          var(--surfaceSecondary) !important;

        border-top-left-radius: 0 !important;
        border-top-right-radius: 0 !important;
      }
    `;

    document.head.appendChild(style);
  }

  function removeOldCustomUi(host) {
    if (!(host instanceof HTMLElement)) {
      return;
    }

    host
      .querySelectorAll(
        ":scope > ." + BUTTON_CLASS +
        ", :scope > ." + MENU_CLASS
      )
      .forEach((element) => element.remove());
  }

  function createIcon(className, label) {
    const spec = iconForSource(label);

    const icon = document.createElement("i");
    icon.className =
      "material-symbols " + className;

    icon.textContent = spec.symbol;
    icon.dataset.kind = spec.kind;
    icon.setAttribute("aria-hidden", "true");

    return icon;
  }

  function closeMenu(host, button) {
    if (!(host instanceof HTMLElement)) {
      return;
    }

    host.querySelector(
      ":scope > ." + MENU_CLASS
    )?.remove();

    if (button instanceof HTMLButtonElement) {
      button.setAttribute(
        "aria-expanded",
        "false"
      );
    }
  }

  function focusOption(menu, index) {
    if (!(menu instanceof HTMLElement)) {
      return;
    }

    const options = Array.from(
      menu.querySelectorAll(
        ":scope > button." + OPTION_CLASS
      )
    );

    if (!options.length) {
      return;
    }

    const safe =
      (index + options.length) %
      options.length;

    options[safe]?.focus();
  }

  function navigate(proxy, value) {
    if (
      !proxy ||
      typeof proxy.navigateToSource !== "function"
    ) {
      return false;
    }

    try {
      proxy.navigateToSource(value);
      return true;
    } catch (error) {
      console.warn(
        "Plexpoint source navigation failed",
        error
      );
      return false;
    }
  }

  function openMenu(
    host,
    button,
    proxy,
    options,
    activeValue
  ) {
    closeMenu(host, button);

    const menu = document.createElement("div");
    menu.className = MENU_CLASS;
    menu.setAttribute("role", "menu");
    menu.setAttribute(
      "aria-label",
      "Choose location"
    );

    let folderDividerAdded = false;

    for (const entry of options) {
      const option = document.createElement(
        "button"
      );

      option.type = "button";
      option.className = OPTION_CLASS;
      option.setAttribute("role", "menuitem");

      const isCurrent =
        String(entry.value) ===
        String(activeValue);

      option.setAttribute(
        "aria-current",
        isCurrent ? "true" : "false"
      );

      if (
        entry.kind === "folder" &&
        !folderDividerAdded
      ) {
        option.classList.add(
          "plexpoint-v35-folder-start"
        );

        folderDividerAdded = true;
      }

      const icon = createIcon(
        "plexpoint-v35-option-icon",
        entry.label
      );

      const label = document.createElement(
        "span"
      );

      label.className =
        "plexpoint-v35-option-label";

      label.textContent = entry.label;

      option.append(icon, label);

      option.addEventListener(
        "click",
        (event) => {
          event.preventDefault();
          event.stopPropagation();

          closeMenu(host, button);

          if (!isCurrent) {
            navigate(
              proxy,
              entry.value
            );
          }

          button.focus();
        }
      );

      option.addEventListener(
        "keydown",
        (event) => {
          const buttons = Array.from(
            menu.querySelectorAll(
              ":scope > button." +
              OPTION_CLASS
            )
          );

          const index =
            buttons.indexOf(option);

          if (event.key === "ArrowDown") {
            event.preventDefault();
            focusOption(
              menu,
              index + 1
            );
          } else if (
            event.key === "ArrowUp"
          ) {
            event.preventDefault();
            focusOption(
              menu,
              index - 1
            );
          } else if (
            event.key === "Home"
          ) {
            event.preventDefault();
            focusOption(menu, 0);
          } else if (
            event.key === "End"
          ) {
            event.preventDefault();
            focusOption(
              menu,
              buttons.length - 1
            );
          } else if (
            event.key === "Escape"
          ) {
            event.preventDefault();

            closeMenu(
              host,
              button
            );

            button.focus();
          }
        }
      );

      menu.appendChild(option);
    }

    host.appendChild(menu);

    button.setAttribute(
      "aria-expanded",
      "true"
    );

    const currentIndex = options.findIndex(
      (entry) =>
        String(entry.value) ===
        String(activeValue)
    );

    requestAnimationFrame(() => {
      focusOption(
        menu,
        currentIndex >= 0
          ? currentIndex
          : 0
      );
    });
  }

  function render() {
    if (rendering) {
      return;
    }

    rendering = true;

    try {
      injectStyle();

      const host = document.querySelector(
        "#sidebar .source-card-container"
      );

      if (!(host instanceof HTMLElement)) {
        return;
      }

      const proxy = findLinksProxy();

      if (!proxy) {
        return;
      }

      const options =
        normalizedSourceOptions(proxy);

      if (!options.length) {
        return;
      }

      const activeValue =
        proxy.activeSource ??
        proxy.currentSource ??
        "";

      const activeEntry =
        options.find(
          (entry) =>
            String(entry.value) ===
            String(activeValue)
        ) ||
        options[0];

      const existingButton =
        host.querySelector(
          ":scope > ." + BUTTON_CLASS
        );

      /*
       * Rebuild only when source identity or option set changes.
       */
      const signature = JSON.stringify({
        active: String(activeValue),
        options: options.map(
          (entry) => [
            String(entry.value),
            entry.label,
          ]
        ),
      });

      if (
        existingButton instanceof HTMLButtonElement &&
        existingButton.dataset.signature ===
          signature
      ) {
        return;
      }

      removeOldCustomUi(host);

      host.classList.add(HOST_CLASS);

      const button =
        document.createElement("button");

      button.type = "button";
      button.className = BUTTON_CLASS;
      button.dataset.signature = signature;

      button.setAttribute(
        "aria-haspopup",
        "menu"
      );

      button.setAttribute(
        "aria-expanded",
        "false"
      );

      button.setAttribute(
        "aria-label",
        "Change location"
      );

      const icon = createIcon(
        "plexpoint-v35-source-icon",
        activeEntry.label
      );

      const label =
        document.createElement("span");

      label.className =
        "plexpoint-v35-source-label";

      label.textContent =
        activeEntry.label;

      const chevron =
        document.createElement("i");

      chevron.className =
        "material-symbols " +
        "plexpoint-v35-source-chevron";

      chevron.textContent =
        "expand_more";

      chevron.setAttribute(
        "aria-hidden",
        "true"
      );

      button.append(
        icon,
        label,
        chevron
      );

      button.addEventListener(
        "click",
        (event) => {
          event.preventDefault();
          event.stopPropagation();

          const open =
            button.getAttribute(
              "aria-expanded"
            ) === "true";

          if (open) {
            closeMenu(
              host,
              button
            );
          } else {
            openMenu(
              host,
              button,
              proxy,
              options,
              activeValue
            );
          }
        }
      );

      button.addEventListener(
        "keydown",
        (event) => {
          if (
            event.key !== "ArrowDown" &&
            event.key !== "ArrowUp"
          ) {
            return;
          }

          event.preventDefault();

          const open =
            button.getAttribute(
              "aria-expanded"
            ) === "true";

          if (!open) {
            openMenu(
              host,
              button,
              proxy,
              options,
              activeValue
            );
          }
        }
      );

      host.appendChild(button);
    } finally {
      rendering = false;
    }
  }

  function scheduleRender() {
    if (frame !== null) {
      return;
    }

    frame = requestAnimationFrame(() => {
      frame = null;
      render();
    });
  }

  function handleOutsidePointer(event) {
    const host = document.querySelector(
      "#sidebar ." + HOST_CLASS
    );

    if (!(host instanceof HTMLElement)) {
      return;
    }

    const button = host.querySelector(
      ":scope > ." + BUTTON_CLASS
    );

    if (!(button instanceof HTMLButtonElement)) {
      return;
    }

    if (
      button.getAttribute(
        "aria-expanded"
      ) !== "true"
    ) {
      return;
    }

    if (
      event.target instanceof Node &&
      host.contains(event.target)
    ) {
      return;
    }

    closeMenu(host, button);
  }

  function handleEscape(event) {
    if (event.key !== "Escape") {
      return;
    }

    const host = document.querySelector(
      "#sidebar ." + HOST_CLASS
    );

    if (!(host instanceof HTMLElement)) {
      return;
    }

    const button = host.querySelector(
      ":scope > ." + BUTTON_CLASS
    );

    if (!(button instanceof HTMLButtonElement)) {
      return;
    }

    if (
      button.getAttribute(
        "aria-expanded"
      ) !== "true"
    ) {
      return;
    }

    closeMenu(host, button);
    button.focus();
  }

  function start() {
    injectStyle();
    render();

    const observer =
      new MutationObserver(
        scheduleRender
      );

    observer.observe(
      document.documentElement,
      {
        childList: true,
        subtree: true,
        characterData: true,
      }
    );

    document.addEventListener(
      "pointerdown",
      handleOutsidePointer,
      true
    );

    document.addEventListener(
      "keydown",
      handleEscape,
      true
    );

    window.addEventListener(
      "pageshow",
      scheduleRender,
      { passive: true }
    );

    window.addEventListener(
      "popstate",
      scheduleRender,
      { passive: true }
    );

    window.addEventListener(
      "hashchange",
      scheduleRender,
      { passive: true }
    );
  }

  if (
    document.readyState === "loading"
  ) {
    document.addEventListener(
      "DOMContentLoaded",
      start,
      { once: true }
    );
  } else {
    start();
  }
})();

/* === Plexpoint Explorer V37: close Sort/View/More menus on outside click === */
(function () {
  "use strict";

  const MENU_CONFIG = {
    "plexpoint-explorer-sort-menu": "sort",
    "plexpoint-explorer-view-menu": "view",
    "plexpoint-explorer-more-menu": "more",
  };

  const SORT_MORE_ID =
    "plexpoint-explorer-sort-more-menu";

  function toolbarTrigger(action) {
    const element = document.querySelector(
      `#plexpoint-explorer-toolbar
       .plexpoint-explorer-tool[data-explorer-action="${action}"]`
    );

    return element instanceof HTMLElement
      ? element
      : null;
  }

  function isInside(element, target) {
    return Boolean(
      element instanceof HTMLElement &&
      target instanceof Node &&
      element.contains(target)
    );
  }

  function closeMenu(id) {
    document.getElementById(id)?.remove();

    /*
     * The Sort "More" side-menu belongs to Sort, so it must disappear when
     * the main Sort popup closes as well.
     */
    if (id === "plexpoint-explorer-sort-menu") {
      document.getElementById(
        SORT_MORE_ID
      )?.remove();
    }
  }

  function onPointerDown(event) {
    const target =
      event.target instanceof Node
        ? event.target
        : null;

    if (!target) return;

    /*
     * SORT
     *
     * Keep it open when:
     * - clicking inside the Sort popup,
     * - clicking inside its More submenu,
     * - clicking the Sort toolbar button itself.
     *
     * The existing Sort-button click handler will perform its normal toggle.
     */
    const sortMenu = document.getElementById(
      "plexpoint-explorer-sort-menu"
    );

    if (sortMenu instanceof HTMLElement) {
      const sortMore = document.getElementById(
        SORT_MORE_ID
      );

      const sortTrigger =
        toolbarTrigger("sort");

      const keepSortOpen =
        isInside(sortMenu, target) ||
        isInside(sortMore, target) ||
        isInside(sortTrigger, target);

      if (!keepSortOpen) {
        closeMenu(
          "plexpoint-explorer-sort-menu"
        );
      }
    }

    /*
     * VIEW
     */
    const viewMenu = document.getElementById(
      "plexpoint-explorer-view-menu"
    );

    if (viewMenu instanceof HTMLElement) {
      const viewTrigger =
        toolbarTrigger("view");

      const keepViewOpen =
        isInside(viewMenu, target) ||
        isInside(viewTrigger, target);

      if (!keepViewOpen) {
        closeMenu(
          "plexpoint-explorer-view-menu"
        );
      }
    }

    /*
     * THREE DOTS / MORE
     */
    const moreMenu = document.getElementById(
      "plexpoint-explorer-more-menu"
    );

    if (moreMenu instanceof HTMLElement) {
      const moreTrigger =
        toolbarTrigger("more");

      const keepMoreOpen =
        isInside(moreMenu, target) ||
        isInside(moreTrigger, target);

      if (!keepMoreOpen) {
        closeMenu(
          "plexpoint-explorer-more-menu"
        );
      }
    }
  }

  /*
   * Capture phase is intentional:
   * toolbar buttons call stopPropagation(), so a normal bubbling listener
   * would never see clicks on them.
   */
  document.addEventListener(
    "pointerdown",
    onPointerDown,
    true
  );

  /*
   * Also close these menus if the browser tab/window loses focus.
   * This prevents a popup remaining visually stuck after Alt+Tab.
   */
  window.addEventListener(
    "blur",
    () => {
      for (const id of Object.keys(MENU_CONFIG)) {
        closeMenu(id);
      }
    }
  );
})();



/* === Plexpoint Explorer V44: preserve FileBrowser built-in scrolling, fix 111px shell mismatch safely === */
(function () {
  "use strict";

  const STYLE_ID =
    "plexpoint-v44-built-in-scroll-geometry-safe-style";

  function injectStyle() {
    if (document.getElementById(STYLE_ID)) return;

    const style = document.createElement("style");
    style.id = STYLE_ID;

    style.textContent = `
      @media (min-width: 769px) {
        /*
         * Keep #main as FileBrowser's real scroll container.
         * Do NOT move it to a new viewport like V43 did.
         */
        body.plexpoint-explorer-layout #main.scrollable {
          overflow-x: hidden !important;
          overflow-y: scroll !important;

          -webkit-overflow-scrolling: touch !important;
        }

        /*
         * The Explorer shell is 111px-ish tall, but putting that whole value
         * into #main's padding created the exact 111px down->snap-up mismatch
         * captured by V42.
         *
         * Restore FileBrowser's own internal header spacing for the scroller.
         */
        body.plexpoint-explorer-layout #main {
          top: 0 !important;
          bottom: 0 !important;
          height: 100% !important;
          min-height: 0 !important;

          padding-top:
            var(--header-height) !important;

          box-sizing:
            border-box !important;
        }

        /*
         * The visible custom Explorer shell is taller than FileBrowser's
         * native header. Keep visual content below it using the listing root,
         * not by enlarging the scroll container's own padding.
         *
         * For Details, the shelf/header still occupies its own space.
         */
        body.plexpoint-explorer-layout.plexpoint-view-details
          .listing-view-root {
          padding-top:
            calc(
              2.9rem +
              (
                var(--plexpoint-explorer-content-top) -
                var(--header-height)
              )
            ) !important;
        }

        /*
         * Non-Details views previously used almost no root padding because the
         * full 111px was inside #main. Add only the DIFFERENCE here.
         */
        body.plexpoint-explorer-layout:not(.plexpoint-view-details):not(.plexpoint-home-dashboard)
          .listing-view-root {
          padding-top:
            calc(
              .15rem +
              (
                var(--plexpoint-explorer-content-top) -
                var(--header-height)
              )
            ) !important;
        }

        /*
         * Home stays isolated, as requested. It gets the same shell-difference
         * compensation without inheriting normal-folder view rules.
         */
        body.plexpoint-explorer-layout.plexpoint-home-dashboard
          .listing-view-root {
          padding-top:
            calc(
              (
                var(--plexpoint-explorer-content-top) -
                var(--header-height)
              )
            ) !important;
        }

        /*
         * Shelf/sidebar remain visually aligned to the custom shell.
         */
        body.plexpoint-explorer-layout #shelf,
        body.plexpoint-explorer-layout #sidebar {
          top:
            var(--plexpoint-explorer-content-top) !important;
        }
      }
    `;

    document.head.appendChild(style);
  }

  if (document.readyState === "loading") {
    document.addEventListener(
      "DOMContentLoaded",
      injectStyle,
      { once: true }
    );
  } else {
    injectStyle();
  }
})();



