/* === Plexpoint Explorer V48: keep Details category Shelf permanently visible === */
(function () {
  "use strict";

  const STYLE_ID =
    "plexpoint-v48-category-shelf-never-hides-style";

  const PATCH_FLAG =
    "__plexpointV48ShelfPatched";

  const ORIGINAL_ATTACH =
    "__plexpointV48OriginalAttachScrollListener";

  const ORIGINAL_DETACH =
    "__plexpointV48OriginalDetachScrollListener";

  let frame = null;

  function shouldLockShelf() {
    return Boolean(
      document.body.classList.contains(
        "plexpoint-explorer-layout"
      ) &&
      document.body.classList.contains(
        "plexpoint-view-details"
      ) &&
      !document.body.classList.contains(
        "plexpoint-home-dashboard"
      ) &&
      !document.body.classList.contains(
        "plexpoint-search-results-active"
      )
    );
  }

  function injectStyle() {
    if (document.getElementById(STYLE_ID)) {
      return;
    }

    const style =
      document.createElement("style");

    style.id = STYLE_ID;

    style.textContent = `
      @media (min-width: 769px) {
        /*
         * Normal Details pages only.
         *
         * JS below prevents Shelf.vue from setting isHidden=true.
         * These rules make the visual state equally unambiguous.
         */
        body.plexpoint-explorer-layout.plexpoint-view-details:not(.plexpoint-home-dashboard):not(.plexpoint-search-results-active)
          #shelf {
          display:
            block !important;

          visibility:
            visible !important;

          opacity:
            1 !important;

          transform:
            translateY(0) !important;

          transition:
            none !important;
        }

        body.plexpoint-explorer-layout.plexpoint-view-details:not(.plexpoint-home-dashboard):not(.plexpoint-search-results-active)
          #shelf
          .listing-item-header {
          visibility:
            visible !important;

          opacity:
            1 !important;

          transform:
            none !important;
        }

        body.plexpoint-explorer-layout.plexpoint-view-details:not(.plexpoint-home-dashboard):not(.plexpoint-search-results-active)
          .shelf-slide-enter-active,
        body.plexpoint-explorer-layout.plexpoint-view-details:not(.plexpoint-home-dashboard):not(.plexpoint-search-results-active)
          .shelf-slide-leave-active,
        body.plexpoint-explorer-layout.plexpoint-view-details:not(.plexpoint-home-dashboard):not(.plexpoint-search-results-active)
          .shelf-slide-enter-from,
        body.plexpoint-explorer-layout.plexpoint-view-details:not(.plexpoint-home-dashboard):not(.plexpoint-search-results-active)
          .shelf-slide-leave-to,
        body.plexpoint-explorer-layout.plexpoint-view-details:not(.plexpoint-home-dashboard):not(.plexpoint-search-results-active)
          .shelf-slide-enter-to,
        body.plexpoint-explorer-layout.plexpoint-view-details:not(.plexpoint-home-dashboard):not(.plexpoint-search-results-active)
          .shelf-slide-leave-from {
          transition:
            none !important;

          transform:
            translateY(0) !important;

          opacity:
            1 !important;
        }
      }
    `;

    document.head.appendChild(style);
  }

  function vueInstanceFromElement(element) {
    if (!(element instanceof Element)) {
      return null;
    }

    if (element.__vueParentComponent) {
      return element.__vueParentComponent;
    }

    for (const key of Object.keys(element)) {
      if (
        key.startsWith(
          "__vueParentComponent"
        ) &&
        element[key]
      ) {
        return element[key];
      }
    }

    return null;
  }

  function findShelfProxy() {
    const shelf =
      document.getElementById("shelf");

    if (!(shelf instanceof HTMLElement)) {
      return null;
    }

    /*
     * Vue 2 fallback.
     */
    if (shelf.__vue__) {
      let component = shelf.__vue__;
      let depth = 0;

      while (
        component &&
        depth < 20
      ) {
        const name =
          String(
            component.$options?.name ||
            ""
          ).toLowerCase();

        if (
          name === "shelf" ||
          (
            typeof component.attachScrollListener ===
              "function" &&
            typeof component.detachScrollListener ===
              "function" &&
            "isHidden" in component
          )
        ) {
          return component;
        }

        component =
          component.$parent ||
          null;

        depth += 1;
      }
    }

    /*
     * Current Quantum / Vue 3.
     */
    let instance =
      vueInstanceFromElement(shelf);

    let depth = 0;

    while (
      instance &&
      depth < 30
    ) {
      const proxy =
        instance.proxy ||
        instance.ctx ||
        instance.exposed ||
        null;

      const name =
        String(
          instance.type?.name ||
          instance.type?.__name ||
          proxy?.$options?.name ||
          ""
        ).toLowerCase();

      if (
        proxy &&
        (
          name === "shelf" ||
          (
            typeof proxy.attachScrollListener ===
              "function" &&
            typeof proxy.detachScrollListener ===
              "function" &&
            "isHidden" in proxy
          )
        )
      ) {
        return proxy;
      }

      instance =
        instance.parent ||
        null;

      depth += 1;
    }

    return null;
  }

  function patchShelf() {
    const shelf =
      findShelfProxy();

    if (!shelf) {
      return;
    }

    if (!shelf[PATCH_FLAG]) {
      /*
       * First remove FileBrowser's currently-attached native Shelf scroll
       * listener using its ORIGINAL method references.
       */
      const originalAttach =
        shelf.attachScrollListener;

      const originalDetach =
        shelf.detachScrollListener;

      try {
        originalDetach.call(shelf);
      } catch {}

      try {
        shelf[ORIGINAL_ATTACH] =
          originalAttach;

        shelf[ORIGINAL_DETACH] =
          originalDetach;
      } catch {}

      /*
       * Replace attachScrollListener rather than touching #main scrolling.
       *
       * In normal Explorer Details mode:
       *   - Shelf stays visible
       *   - no auto-hide scroll listener is attached
       *
       * Outside that mode:
       *   - FileBrowser can use its normal Shelf behavior.
       */
      shelf.attachScrollListener =
        function plexpointV48AttachShelf() {
          if (shouldLockShelf()) {
            try {
              this.isHidden = false;
              this.lastScrollTop = 0;
              this.scrollElement = null;
            } catch {}

            return;
          }

          return originalAttach.call(
            this
          );
        };

      try {
        shelf[PATCH_FLAG] = true;
      } catch {}
    }

    /*
     * If this is a normal Details folder right now, guarantee the native
     * listener is detached and the reactive v-show state is visible.
     */
    if (shouldLockShelf()) {
      try {
        const detach =
          shelf[ORIGINAL_DETACH] ||
          shelf.detachScrollListener;

        detach.call(shelf);
      } catch {}

      try {
        if (shelf.scrollFrame) {
          cancelAnimationFrame(
            shelf.scrollFrame
          );

          shelf.scrollFrame = null;
        }
      } catch {}

      try {
        shelf.isHidden = false;
        shelf.lastScrollTop = 0;
        shelf.scrollElement = null;
      } catch {}
    }
  }

  function schedulePatch() {
    if (frame !== null) {
      return;
    }

    frame =
      requestAnimationFrame(
        () => {
          frame = null;

          injectStyle();
          patchShelf();
        }
      );
  }

  function start() {
    injectStyle();
    patchShelf();

    /*
     * Route/view changes can remount Shelf.vue.
     * Re-patch only when the DOM structure/class state changes.
     *
     * This observer does NOT read or change scrollTop.
     */
    const observer =
      new MutationObserver(
        schedulePatch
      );

    observer.observe(
      document.documentElement,
      {
        childList: true,
        subtree: true,
        attributes: true,
        attributeFilter: [
          "class",
        ],
      }
    );

    window.addEventListener(
      "popstate",
      schedulePatch,
      {
        passive: true,
      }
    );

    window.addEventListener(
      "hashchange",
      schedulePatch,
      {
        passive: true,
      }
    );

    window.addEventListener(
      "pageshow",
      schedulePatch,
      {
        passive: true,
      }
    );
  }

  if (
    document.readyState ===
    "loading"
  ) {
    document.addEventListener(
      "DOMContentLoaded",
      start,
      {
        once: true,
      }
    );
  } else {
    start();
  }
})();



