/* === Plexpoint Explorer V75: mixed folder + file Ctrl multi-selection === */
(function () {
  "use strict";

  let swallowClickUntil = 0;
  let swallowRow = null;

  function isNormalListing() {
    return Boolean(
      document.body.classList.contains(
        "plexpoint-explorer-layout"
      ) &&
      !document.body.classList.contains(
        "plexpoint-home-dashboard"
      )
    );
  }

  function selectionArray() {
    const view =
      typeof listingView === "function"
        ? listingView()
        : null;

    const state =
      view?.state ||
      null;

    return Array.isArray(
      state?.selected
    )
      ? state.selected
      : null;
  }

  function rowSelectionValue(row) {
    if (!(row instanceof HTMLElement)) {
      return null;
    }

    const raw =
      String(
        row.dataset.index ?? ""
      ).trim();

    if (!raw) {
      return null;
    }

    const numeric =
      Number(raw);

    return (
      Number.isInteger(numeric) &&
      String(numeric) === raw
    )
      ? numeric
      : raw;
  }

  function selectionIdentity(value) {
    if (
      typeof explorerSelectionIdentity ===
      "function"
    ) {
      return explorerSelectionIdentity(
        value
      );
    }

    if (
      value &&
      typeof value === "object" &&
      value.index !== undefined
    ) {
      return (
        "index:" +
        String(value.index)
      );
    }

    return (
      "index:" +
      String(value)
    );
  }

  function refreshSelectionUi() {
    if (
      typeof explorerRefreshSelectionUi ===
      "function"
    ) {
      explorerRefreshSelectionUi();
    }

    /*
     * Give Vue one tick to repaint selected row state.
     */
    requestAnimationFrame(
      () => {
        if (
          typeof updateExplorerToolbarState ===
          "function"
        ) {
          updateExplorerToolbarState();
        }
      }
    );
  }

  function toggleMixedSelection(row) {
    const selected =
      selectionArray();

    const value =
      rowSelectionValue(row);

    if (
      !selected ||
      value === null
    ) {
      return false;
    }

    const wanted =
      selectionIdentity(value);

    const existingIndex =
      selected.findIndex(
        (entry) =>
          selectionIdentity(entry) ===
          wanted
      );

    if (existingIndex >= 0) {
      selected.splice(
        existingIndex,
        1
      );
    } else {
      /*
       * Important:
       * do NOT clear existing entries based on directory/file type.
       * Folders and files can coexist in this same selected[] array.
       */
      selected.push(value);
    }

    refreshSelectionUi();

    return true;
  }

  function eligibleRow(target) {
    if (
      !(target instanceof Element)
    ) {
      return null;
    }

    const row =
      target.closest(
        ".listing-view-root " +
        ".listing-item[data-index][data-name]"
      );

    if (
      !(row instanceof HTMLElement)
    ) {
      return null;
    }

    if (
      row.classList.contains(
        "plexpoint-synthetic-home-pin"
      )
    ) {
      return null;
    }

    return row;
  }

  function onPointerDown(event) {
    if (
      !isNormalListing() ||
      event.button !== 0 ||
      !(event.ctrlKey || event.metaKey) ||
      event.altKey ||
      event.shiftKey
    ) {
      return;
    }

    const row =
      eligibleRow(
        event.target
      );

    if (!row) {
      return;
    }

    /*
     * Take over ONLY modifier-click selection before Quantum can apply
     * any folder-vs-file selection policy.
     */
    event.preventDefault();
    event.stopPropagation();
    event.stopImmediatePropagation();

    if (
      toggleMixedSelection(row)
    ) {
      swallowRow = row;
      swallowClickUntil =
        performance.now() + 450;
    }
  }

  function onClick(event) {
    if (
      performance.now() >
      swallowClickUntil
    ) {
      swallowRow = null;
      return;
    }

    const row =
      eligibleRow(
        event.target
      );

    if (
      !row ||
      row !== swallowRow
    ) {
      return;
    }

    /*
     * Prevent the click generated after our handled pointerdown from opening
     * a folder/file. Ctrl-click should only toggle selection.
     */
    event.preventDefault();
    event.stopPropagation();
    event.stopImmediatePropagation();

    swallowRow = null;
    swallowClickUntil = 0;
  }

  function start() {
    /*
     * Capture phase is intentional: this runs before FileBrowser's own
     * selection/open handlers.
     */
    window.addEventListener(
      "pointerdown",
      onPointerDown,
      true
    );

    window.addEventListener(
      "click",
      onClick,
      true
    );
  }

  if (
    document.readyState ===
    "loading"
  ) {
    document.addEventListener(
      "DOMContentLoaded",
      start,
      {
        once: true,
      }
    );
  } else {
    start();
  }
})();



