/* === Plexpoint Explorer V79: make selected FOLDERS visibly stay highlighted === */
(function () {
  "use strict";

  const STYLE_ID =
    "plexpoint-v79-folder-selection-highlight-style";

  const VISUAL_CLASS =
    "plexpoint-v79-selected";

  let syncFrame = null;
  let observedStatus = null;
  let statusObserver = null;
  let observedListing = null;
  let listingObserver = null;

  function injectStyle() {
    if (document.getElementById(STYLE_ID)) {
      return;
    }

    const style =
      document.createElement("style");

    style.id = STYLE_ID;

    style.textContent = `
      @media (min-width: 769px) {
        /*
         * Strong selector specifically covers folder rows as well as files.
         * This comes after all older listing-row backgrounds.
         */
        body.plexpoint-explorer-layout:not(.plexpoint-home-dashboard)
          .listing-view-root
          .listing-item.${VISUAL_CLASS},
        body.plexpoint-explorer-layout:not(.plexpoint-home-dashboard)
          .listing-view-root
          .folder-items
          .listing-item.${VISUAL_CLASS},
        body.plexpoint-explorer-layout:not(.plexpoint-home-dashboard)
          .listing-view-root
          .file-items
          .listing-item.${VISUAL_CLASS} {
          background:
            color-mix(
              in srgb,
              var(--primaryColor, #2196f3) 30%,
              var(--plexpoint-explorer-base) 70%
            ) !important;

          color:
            var(--plexpoint-explorer-text) !important;

          border-color:
            color-mix(
              in srgb,
              var(--primaryColor, #2196f3) 75%,
              transparent
            ) !important;

          box-shadow:
            inset 0 0 0 1px
            color-mix(
              in srgb,
              var(--primaryColor, #2196f3) 68%,
              transparent
            ) !important;
        }

        body.plexpoint-explorer-layout:not(.plexpoint-home-dashboard)
          .listing-view-root
          .listing-item.${VISUAL_CLASS}:hover {
          background:
            color-mix(
              in srgb,
              var(--primaryColor, #2196f3) 38%,
              var(--plexpoint-explorer-base) 62%
            ) !important;
        }

        /*
         * Home stays completely non-selectable visually.
         */
        body.plexpoint-explorer-layout.plexpoint-home-dashboard
          .listing-item.${VISUAL_CLASS} {
          background:
            var(--plexpoint-explorer-base) !important;

          border-color:
            transparent !important;

          box-shadow:
            none !important;
        }
      }
    `;

    document.head.appendChild(style);
  }

  function listingProxy() {
    const root =
      document.querySelector(
        ".listing-view-root"
      );

    if (!(root instanceof Element)) {
      return null;
    }

    if (root.__vue__) {
      let component = root.__vue__;
      let depth = 0;

      while (
        component &&
        depth < 20
      ) {
        if (
          component.state &&
          Array.isArray(
            component.state.selected
          )
        ) {
          return component;
        }

        component =
          component.$parent ||
          null;

        depth += 1;
      }
    }

    let instance =
      root.__vueParentComponent ||
      null;

    let depth = 0;

    while (
      instance &&
      depth < 25
    ) {
      const proxy =
        instance.proxy ||
        instance.ctx ||
        instance.exposed ||
        null;

      if (
        proxy?.state &&
        Array.isArray(
          proxy.state.selected
        )
      ) {
        return proxy;
      }

      instance =
        instance.parent ||
        null;

      depth += 1;
    }

    return null;
  }

  function identityForItem(item) {
    if (
      !item ||
      typeof item !== "object"
    ) {
      return "";
    }

    const source =
      String(
        item.source ||
        ""
      ).trim();

    const name =
      String(
        item.name ||
        ""
      ).trim();

    let path =
      String(
        item.path ||
        item.from ||
        ""
      ).trim();

    /*
     * Name is the most useful stable fallback for rendered rows in the
     * current directory, especially when Quantum's data-index differs from
     * the raw req.items array index for folder groups.
     */
    return `${source}\n${path}\n${name}`;
  }

  function selectedState() {
    const view =
      listingProxy();

    const selected =
      Array.isArray(
        view?.state?.selected
      )
        ? view.state.selected
        : [];

    const reqItems =
      Array.isArray(
        view?.state?.req?.items
      )
        ? view.state.req.items
        : (
            Array.isArray(
              view?.req?.items
            )
              ? view.req.items
              : []
          );

    const indexes =
      new Set();

    const names =
      new Set();

    const identities =
      new Set();

    for (const entry of selected) {
      if (
        typeof entry === "number" ||
        typeof entry === "string"
      ) {
        const raw =
          String(entry).trim();

        indexes.add(raw);

        /*
         * Critical V79 fix:
         * resolve the selected numeric index back to its real item.
         * This gives folder selections a stable NAME fallback even if the
         * rendered folder row's data-index is not the same as req.items index.
         */
        const numeric =
          Number(raw);

        if (
          Number.isInteger(numeric) &&
          numeric >= 0 &&
          numeric < reqItems.length
        ) {
          const item =
            reqItems[numeric];

          const name =
            String(
              item?.name ||
              ""
            ).trim();

          if (name) {
            names.add(name);
          }

          const identity =
            identityForItem(item);

          if (identity) {
            identities.add(identity);
          }
        }

        continue;
      }

      if (
        !entry ||
        typeof entry !== "object"
      ) {
        continue;
      }

      if (
        entry.index !== undefined &&
        entry.index !== null
      ) {
        indexes.add(
          String(entry.index)
        );
      }

      const directIndex =
        reqItems.indexOf(entry);

      if (directIndex >= 0) {
        indexes.add(
          String(directIndex)
        );
      }

      const name =
        String(
          entry.name ||
          ""
        ).trim();

      if (name) {
        names.add(name);
      }

      const identity =
        identityForItem(entry);

      if (identity) {
        identities.add(identity);
      }
    }

    return {
      indexes,
      names,
      identities,
    };
  }

  function rowLooksSelected(
    row,
    state
  ) {
    const index =
      String(
        row.dataset.index ??
        ""
      ).trim();

    const name =
      String(
        row.dataset.name ??
        ""
      ).trim();

    if (
      index &&
      state.indexes.has(index)
    ) {
      return true;
    }

    if (
      name &&
      state.names.has(name)
    ) {
      return true;
    }

    /*
     * Keep FileBrowser's own rendered markers as valid evidence too.
     */
    if (
      row.getAttribute(
        "aria-selected"
      ) === "true" ||
      row.classList.contains(
        "activebutton"
      ) ||
      row.classList.contains(
        "selected"
      ) ||
      row.classList.contains(
        "is-selected"
      )
    ) {
      return true;
    }

    return false;
  }

  function syncSelectionVisuals() {
    syncFrame = null;

    const rows =
      document.querySelectorAll(
        ".listing-view-root " +
        ".listing-item[data-name]"
      );

    if (
      document.body.classList.contains(
        "plexpoint-home-dashboard"
      )
    ) {
      for (const row of rows) {
        row.classList.remove(
          VISUAL_CLASS
        );
      }

      return;
    }

    const state =
      selectedState();

    for (const row of rows) {
      if (!(row instanceof HTMLElement)) {
        continue;
      }

      if (
        row.classList.contains(
          "plexpoint-synthetic-home-pin"
        )
      ) {
        row.classList.remove(
          VISUAL_CLASS
        );

        continue;
      }

      row.classList.toggle(
        VISUAL_CLASS,
        rowLooksSelected(
          row,
          state
        )
      );
    }
  }

  function scheduleSync() {
    if (syncFrame !== null) {
      return;
    }

    syncFrame =
      requestAnimationFrame(
        syncSelectionVisuals
      );
  }

  function attachObservers() {
    const status =
      document.getElementById(
        "status-bar"
      );

    if (status !== observedStatus) {
      statusObserver?.disconnect();
      statusObserver = null;
      observedStatus = status;

      if (status instanceof HTMLElement) {
        statusObserver =
          new MutationObserver(
            scheduleSync
          );

        statusObserver.observe(
          status,
          {
            childList: true,
            subtree: true,
            characterData: true,
          }
        );
      }
    }

    const listing =
      document.querySelector(
        ".listing-view-root"
      );

    if (listing !== observedListing) {
      listingObserver?.disconnect();
      listingObserver = null;
      observedListing = listing;

      if (listing instanceof HTMLElement) {
        listingObserver =
          new MutationObserver(
            scheduleSync
          );

        listingObserver.observe(
          listing,
          {
            childList: true,
            subtree: true,
          }
        );
      }
    }

    scheduleSync();
  }

  function instantCtrlClickHighlight(
    event
  ) {
    if (
      document.body.classList.contains(
        "plexpoint-home-dashboard"
      ) ||
      event.button !== 0 ||
      !(event.ctrlKey || event.metaKey)
    ) {
      return;
    }

    const target =
      event.target;

    if (!(target instanceof Element)) {
      return;
    }

    const row =
      target.closest(
        ".listing-view-root " +
        ".listing-item[data-name]"
      );

    if (!(row instanceof HTMLElement)) {
      return;
    }

    /*
     * V75 toggles the real selected[] state earlier in capture phase.
     * Wait one microtask, then mirror the actual resulting state onto the
     * clicked row immediately so folders never appear unselected.
     */
    queueMicrotask(
      () => {
        const state =
          selectedState();

        row.classList.toggle(
          VISUAL_CLASS,
          rowLooksSelected(
            row,
            state
          )
        );

        scheduleSync();
      }
    );
  }

  function start() {
    injectStyle();
    attachObservers();

    document.addEventListener(
      "pointerdown",
      instantCtrlClickHighlight,
      true
    );

    document.addEventListener(
      "click",
      () => {
        window.setTimeout(
          scheduleSync,
          0
        );
      },
      true
    );

    const structureObserver =
      new MutationObserver(
        attachObservers
      );

    structureObserver.observe(
      document.body,
      {
        childList: true,
        subtree: true,
      }
    );

    window.addEventListener(
      "popstate",
      attachObservers,
      {
        passive: true,
      }
    );

    window.addEventListener(
      "hashchange",
      attachObservers,
      {
        passive: true,
      }
    );

    window.addEventListener(
      "pageshow",
      attachObservers,
      {
        passive: true,
      }
    );
  }

  if (
    document.readyState ===
    "loading"
  ) {
    document.addEventListener(
      "DOMContentLoaded",
      start,
      {
        once: true,
      }
    );
  } else {
    start();
  }
})();



