/* === Plexpoint Explorer V86: repair Pin to Home after SPA/selection changes ===
 * - selected folder is resolved from the real rendered row
 * - V77/V79 visual-selection classes are recognised
 * - current route is authoritative for source/path
 * - stale item.source="Home" is repaired before creating a pin
 * - drive/source roots still cannot be added as duplicate Home folder pins
 */



/* === Plexpoint Explorer V87: rename context-menu "Pin" to "Pin to Home" === */
(function () {
  "use strict";

  let frame = null;

  function relabelPinAction() {
    frame = null;

    const menu =
      document.getElementById("context-menu");

    if (!(menu instanceof HTMLElement)) {
      return;
    }

    const buttons =
      menu.querySelectorAll("button.action");

    for (const button of buttons) {
      const label =
        String(
          button.querySelector("span")?.textContent ||
          button.textContent ||
          ""
        )
          .replace(/\s+/g, " ")
          .trim();

      if (label !== "Pin") {
        continue;
      }

      const span =
        button.querySelector("span");

      if (span instanceof HTMLElement) {
        span.textContent = "Pin to Home";
      } else {
        /*
         * Keep any icon node intact where possible.
         */
        const icon =
          button.querySelector("i");

        if (icon) {
          const textNode =
            Array.from(button.childNodes)
              .find(
                (node) =>
                  node.nodeType ===
                  Node.TEXT_NODE
              );

          if (textNode) {
            textNode.textContent =
              " Pin to Home";
          }
        } else {
          button.textContent =
            "Pin to Home";
        }
      }
    }
  }

  function scheduleRelabel() {
    if (frame !== null) {
      return;
    }

    frame =
      requestAnimationFrame(
        relabelPinAction
      );
  }

  function start() {
    relabelPinAction();

    const observer =
      new MutationObserver(
        scheduleRelabel
      );

    observer.observe(
      document.body,
      {
        childList: true,
        subtree: true,
      }
    );
  }

  if (
    document.readyState ===
    "loading"
  ) {
    document.addEventListener(
      "DOMContentLoaded",
      start,
      {
        once: true,
      }
    );
  } else {
    start();
  }
})();



/* === Plexpoint Explorer V90: stable rollback of V88 Transfer Center ===
 * Built from the last stable V87 baseline.
 *
 * RETAINED:
 * - real Pin to Home / Unpin from Home action
 * - V86 pin resolver
 * - V85 unified sidebar source button
 * - Home top padding 114px
 * - regular listing top padding 162px
 * - sidebar custom icons/order/scrollbar
 * - mixed file+folder selection work
 *
 * ROLLED BACK:
 * - V88 toolbar Transfer Center
 * - V88 per-job rendering
 * - V88 upload-panel MutationObserver interactions
 *
 * Reason: V88 could repeatedly mutate its own job-list DOM while the global
 * customization MutationObserver was watching the same subtree, preventing
 * the normal Explorer layout from settling reliably.
 */


/* === Plexpoint Explorer V104: seamless sidebar/directory route swaps === */
(function () {
  "use strict";

  let frame = null;

  function filesRouteActive() {
    return (
      location.pathname === "/files" ||
      location.pathname.startsWith("/files/")
    );
  }

  function keepExplorerShellAlive() {
    frame = null;

    if (!filesRouteActive()) {
      return;
    }

    document.body.classList.add(
      "plexpoint-explorer-layout"
    );

    /*
     * The main customization MutationObserver rebuilds the actual nav/toolbar.
     * This tiny independent guard only makes the Explorer layout class
     * impossible to lose during a /files route swap.
     */
  }

  function schedule() {
    if (frame !== null) {
      return;
    }

    frame = requestAnimationFrame(
      keepExplorerShellAlive
    );
  }

  /*
   * Vue route swaps are DOM mutations. This observer does not rewrite listing
   * rows and cannot create a mutation loop: after the two shell nodes are in
   * their correct places, both ensure functions become no-ops.
   */
  const observer = new MutationObserver(
    schedule
  );

  observer.observe(
    document.body,
    {
      childList: true,
      subtree: true,
    }
  );

  window.addEventListener(
    "popstate",
    schedule,
    { passive: true }
  );

  window.addEventListener(
    "hashchange",
    schedule,
    { passive: true }
  );

  schedule();
})();

/*
 * V104 root cause:
 * ensureExplorerToolbar()/ensureExplorerNavigationBar() used to tear down the
 * custom Explorer shell whenever .listing-view-root disappeared. FileBrowser
 * intentionally removes that root briefly while changing directories, causing
 * the raw/native FileBrowser interface to flash for a frame. The shell now
 * survives that transient state for every /files route.
 */



/* === Plexpoint Explorer V106: HOME-ONLY pin isolation === */
(function () {
  "use strict";

  function removeLegacyHomePinRows() {
    /*
     * Old Home pins used an invisible U+2063 marker in FileBrowser sidebar
     * link names. If a stale server/user render remains for a moment after
     * migration, hide only those explicitly-marked rows. Normal folders stay.
     *
     * V162 SIDEBAR PINNED-VIEW FIX
     * ----------------------------
     * V160 also stores Plexpoint account preferences in one deliberately
     * invisible Sidebar Link using the same marker family. FileBrowser renders
     * that link only in some sidebar modes (notably its Pinned view).
     *
     * The older selector included every element whose class merely CONTAINED
     * "link". That meant structural containers such as .sidebar-links-content
     * inherited the hidden config link's marker through textContent and the
     * whole sidebar pane was given display:none!important.
     *
     * Work from the deepest marker-bearing link/control instead. Parents that
     * merely contain a marked child are never hidden. This keeps the internal
     * Plexpoint record invisible without blanking FileBrowser's Pinned view.
     */
    const marker = "\u2063\u2063\u2063";
    const candidateSelector = [
      "#sidebar a",
      "#sidebar button",
      '#sidebar [role="link"]',
      '#sidebar [role="button"]',
      "#sidebar .link-item",
      "#sidebar li",
      '#sidebar [class*="sidebar-link"]',
    ].join(", ");

    const nestedSelector = [
      "a",
      "button",
      '[role="link"]',
      '[role="button"]',
      ".link-item",
      "li",
      '[class*="sidebar-link"]',
    ].join(", ");

    for (const element of document.querySelectorAll(candidateSelector)) {
      if (!(element instanceof HTMLElement)) continue;

      const rawText = String(element.textContent || "");
      if (!rawText.includes(marker)) continue;

      /*
       * If a smaller actual link/control below this element owns the marker,
       * leave this parent alone. The descendant will be processed separately.
       */
      const hasMarkedDescendant = Array.from(
        element.querySelectorAll(nestedSelector)
      ).some((child) => (
        child instanceof HTMLElement &&
        child !== element &&
        String(child.textContent || "").includes(marker)
      ));

      if (hasMarkedDescendant) continue;

      /* Prefer the row wrapper so the hidden internal entry leaves no gap. */
      const row =
        element.closest(".link-item, li") ||
        element.closest('a, button, [role="link"], [role="button"]') ||
        element;

      if (!(row instanceof HTMLElement)) continue;

      /* Absolute guard: structural sidebar hosts must never be hidden here. */
      if (
        row.matches(
          ".sidebar-links, .sidebar-links-content, .sidebar-links-header, " +
          ".file-tree-container, .file-tree, .file-tree-root, " +
          ".source-card-container"
        )
      ) {
        continue;
      }

      row.style.setProperty(
        "display",
        "none",
        "important"
      );
    }
  }

  let frame = null;

  const observer = new MutationObserver(
    () => {
      if (frame !== null) return;
      frame = requestAnimationFrame(() => {
        frame = null;
        removeLegacyHomePinRows();
      });
    }
  );

  observer.observe(document.body, {
    childList: true,
    subtree: true,
  });

  removeLegacyHomePinRows();
})();

