        const summary=document.createElement('summary');
        const icon=document.createElement('i');icon.className='material-symbols pp-upload-folder-icon';icon.textContent='folder';icon.setAttribute('aria-hidden','true');
        const label=document.createElement('span');label.className='pp-upload-folder-label';const labelText=textNode(label,data.label);
        const status=document.createElement('span');status.className='pp-upload-folder-status';const statusText=textNode(status);
        const children=document.createElement('div');children.className='pp-upload-children';
        summary.append(icon,label,status);details.append(summary,children);
