      const host = folders.get(info.parent)?.children || ui.list;
      if (entry.card.parentElement !== host) host.appendChild(entry.card);
      const mode = item.complete ? "complete" : item.errors ? "error" : item.paused ? "paused" : item.uploading ? "uploading" : "queued";
      entry.card.dataset.mode = mode;
      const filename = rowName(row) || "Preparing upload…";
      updateUploadIcon(entry, filename);
      setText(entry.nameText, filename);
      entry.name.title = filename;
      const metrics = updateSpeed(item, performance.now(), entry);
      const size = item.total > 0 ? `${formatBytes(item.loaded)} / ${formatBytes(item.total)}` : "";
      const status = mode === "complete" ? "Successful" : mode === "error"
