/* === Plexpoint Explorer V111: notification controls upload background state === */
(function () {
  "use strict";

  const NOTICE_ID =
    "plexpoint-v96-upload-notification";

  let frame =
    null;

  function hasVisibleNonUploadPrompt() {
    for (
      const prompt of
      document.querySelectorAll(
        '.floating-window[aria-label$="-prompt"]'
      )
    ) {
      if (!(prompt instanceof HTMLElement)) {
        continue;
      }

      if (
        prompt.getAttribute(
          "aria-label"
        ) === "upload-prompt"
      ) {
        continue;
      }

      const style =
        getComputedStyle(prompt);

      if (
        style.display === "none" ||
        style.visibility === "hidden" ||
        style.opacity === "0"
      ) {
        continue;
      }

      const rect =
        prompt.getBoundingClientRect();

      if (
        rect.width > 0 &&
        rect.height > 0
      ) {
        return true;
      }
    }

    return false;
  }

  function unlockExplorer() {
    frame =
      null;

    const notice =
      document.getElementById(
        NOTICE_ID
      );

    if (!(notice instanceof HTMLElement)) {
      return;
    }

    /*
     * Preserve proper modal behaviour if the user deliberately opens another
     * real dialog while an upload is running.
     */
    if (
      hasVisibleNonUploadPrompt()
    ) {
      return;
    }

    document.body.classList.remove(
      "plexpoint-modal-prompt-open"
    );

    document
      .getElementById(
        "plexpoint-modal-prompt-backdrop"
      )
      ?.remove();

    /*
     * Clean up any stale interaction state on the large Explorer surfaces.
     */
    for (
      const element of [
        document.getElementById("app"),
        document.getElementById("main"),
        document.getElementById("sidebar"),
        document.querySelector(
          ".listing-view-root"
        ),
      ]
    ) {
      if (!(element instanceof HTMLElement)) {
        continue;
      }

      /*
       * V149: only touch DOM state when it actually needs changing.  V111's
       * MutationObserver watches class/style/inert attributes; repeatedly
       * writing the same inline styles could wake the observer again and turn
       * upload progress + route rendering into a hot requestAnimationFrame
       * loop.  The Tools page is particularly sensitive to that churn.
       */
      if (element.hasAttribute("inert")) {
        element.removeAttribute("inert");
      }

      if (element.style.getPropertyValue("opacity")) {
        element.style.removeProperty("opacity");
      }

      if (element.style.getPropertyValue("filter")) {
        element.style.removeProperty("filter");
      }

      /*
       * Only force pointer-events at the container level. Child buttons/rows
       * retain all their normal hover/disabled behaviour.
       */
      if (
        element.style.getPropertyValue("pointer-events") !== "auto" ||
        element.style.getPropertyPriority("pointer-events") !== "important"
      ) {
        element.style.setProperty(
          "pointer-events",
          "auto",
          "important"
        );
      }
    }
  }

  function schedule() {
    if (
      frame !==
      null
    ) {
      return;
    }

    frame =
      requestAnimationFrame(
        unlockExplorer
      );
  }

  /*
   * Any prompt/backdrop/navigation mutation can happen between upload polling
   * ticks. Reassert the unlocked state on the next animation frame.
   */
  const observer =
    new MutationObserver(
      schedule
    );

  observer.observe(
    document.body,
    {
      childList: true,
      subtree: true,
      attributes: true,
      attributeFilter: [
        "class",
        "style",
        "inert",
      ],
    }
  );

  window.setInterval(
    schedule,
    100
  );

  schedule();
})();

